/* WORLD OF EMPIRES — interactive tutorial: guided practice (spotlight on the real UI) + complete bilingual guide */
(() => {
"use strict";
const UI = window.UI, E = WOE, D = WOE_DATA, T = I18N, A = WOE_AUDIO, t = T.t, esc = UI.esc, $ = UI.$, BUS = window.WOE_BUS;
const L = () => T.lang();
const X = o => o[L()] || o.en;

/* ===================== COMPLETE GUIDE ===================== */
const CH = [
{ t: { en: "Welcome & the goal", fa: "خوش‌آمدید و هدف بازی" }, b: {
  en: `<p>World of Empires is an offline grand-strategy simulation on a real world map. You govern one nation — a real country such as Germany, Brazil or Japan, or a custom island nation — and guide it month by month.</p><h4>What you do</h4><ul><li>Balance the budget, taxes and subsidies.</li><li>Build power plants, schools, ports, mines and more.</li><li>Trade on the global market and manage tariffs.</li><li>Keep citizens satisfied, the country stable and relations healthy.</li><li>Complete the objectives of your chosen scenario.</li></ul><h4>How time works</h4><p>Nothing happens until you press <b>Advance month</b> (or start auto-play). Every month the market, every nation and your own economy are updated.</p>`,
  fa: `<p>«جهان امپراتوری‌ها» یک شبیه‌ساز استراتژی بزرگ آفلاین روی نقشهٔ واقعی جهان است. شما یک کشور را اداره می‌کنید — یک کشور واقعی مثل آلمان، برزیل یا ژاپن، یا یک کشور جزیره‌ای دلخواه — و ماه به ماه آن را هدایت می‌کنید.</p><h4>کارهای شما</h4><ul><li>بودجه، مالیات و یارانه‌ها را متعادل کنید.</li><li>نیروگاه، مدرسه، بندر، معدن و … بسازید.</li><li>در بازار جهانی تجارت کنید و تعرفه‌ها را مدیریت کنید.</li><li>رضایت مردم، ثبات کشور و روابط خارجی را حفظ کنید.</li><li>اهداف سناریوی انتخابی را کامل کنید.</li></ul><h4>زمان چگونه می‌گذرد</h4><p>تا دکمهٔ <b>ماه بعد</b> را نزنید (یا پخش خودکار را روشن نکنید) هیچ اتفاقی نمی‌افتد. در هر ماه بازار، همهٔ کشورها و اقتصاد شما به‌روز می‌شود.</p>` } },
{ t: { en: "Starting a world", fa: "شروع یک جهان" }, b: {
  en: `<p>Press <b>New world</b> on the main screen.</p><ul><li><b>World name</b> – the name of your save.</li><li><b>Country</b> – pick any of 47 real nations or the custom island. Bigger economies have bigger budgets, but every cost scales with your size, so small nations are not weaker in relative terms.</li><li><b>Scenario</b> – the starting situation (see the Scenarios chapter).</li><li><b>Difficulty</b> – Easy, Normal or Hard changes growth and pressure.</li><li><b>Mods</b> – optional rule changes (see the Mods chapter).</li><li><b>Sandbox mode</b> – for testing: unlimited money and resources, every technology, instant construction, research and production, all permissions granted, plus a <b>Sandbox tools</b> panel (advance 12 months, win wars instantly, set prices, trigger events, set all relations).</li></ul><p>Saves are listed on the main screen. <b>Continue</b> opens one; the bin icon deletes it.</p>`,
  fa: `<p>در صفحهٔ اصلی روی <b>جهان جدید</b> بزنید.</p><ul><li><b>نام جهان</b> – نام فایل ذخیرهٔ شما.</li><li><b>کشور</b> – یکی از ۴۷ کشور واقعی یا جزیرهٔ دلخواه. اقتصادهای بزرگ‌تر بودجهٔ بیشتری دارند، اما هزینه‌ها با اندازهٔ شما مقیاس می‌شوند، پس کشورهای کوچک از نظر نسبی ضعیف‌تر نیستند.</li><li><b>سناریو</b> – وضعیت شروع (فصل سناریوها را ببینید).</li><li><b>سختی</b> – آسان، عادی یا سخت رشد و فشار را تغییر می‌دهد.</li><li><b>مودها</b> – تغییرات اختیاری قوانین (فصل مودها).</li><li><b>حالت سند باکس</b> – برای تست: پول و منابع نامحدود، همهٔ فناوری‌ها، ساخت و تحقیق و تولید فوری، همهٔ مجوزها داده‌شده، به‌علاوهٔ پنل <b>ابزار آزمایش</b> (۱۲ ماه جلو رفتن، پیروزی فوری در جنگ، تغییر قیمت‌ها، راه‌اندازی رویداد، تنظیم همهٔ روابط).</li></ul><p>ذخیره‌ها در صفحهٔ اصلی فهرست می‌شوند. <b>ادامه</b> آن را باز می‌کند و آیکن سطل زباله آن را حذف می‌کند.</p>` } },
{ t: { en: "The permanent map", fa: "نقشهٔ دائمی" }, b: {
  en: `<p>The map is always in the centre of the screen; menus open beside it and never replace it.</p><ul><li><b>Zoom</b> with the mouse wheel, the + / − buttons or pinch. <b>Drag</b> to pan. Double-click zooms in.</li><li><b>Click a country</b> to open its card: government, population, GDP, stability, technology, trade and diplomatic actions.</li><li>The globe button fits the whole world; the pin button returns to your country.</li><li>At higher zoom you see <b>cities</b> (diamonds are capitals), <b>rivers</b>, <b>mountain ranges</b>, seas and the world's key <b>chokepoints</b> such as Hormuz and Suez. A chokepoint pulses red when a disruption is active.</li><li><b>Buildings</b> you construct appear as markers inside your own country: a pulsing ring with a progress arc while under construction, a solid badge once finished. Hover or click a marker to see what it is.</li></ul><p>The options button (sliders icon) toggles labels, cities, relief, trade routes and building markers.</p>`,
  fa: `<p>نقشه همیشه در مرکز صفحه است؛ منوها کنار آن باز می‌شوند و هرگز جایش را نمی‌گیرند.</p><ul><li><b>زوم</b> با چرخ ماوس، دکمه‌های + و − یا حرکت دو انگشتی. برای <b>جابه‌جایی</b> بکشید. دابل‌کلیک بزرگ‌نمایی می‌کند.</li><li>روی یک <b>کشور کلیک کنید</b> تا کارت آن باز شود: نوع حکومت، جمعیت، تولید ناخالص، ثبات، فناوری، تجارت و اقدامات دیپلماتیک.</li><li>دکمهٔ کره، کل جهان را در قاب می‌آورد؛ دکمهٔ سنجاق به کشور شما برمی‌گردد.</li><li>با زوم بیشتر <b>شهرها</b> (لوزی‌ها پایتخت‌اند)، <b>رودها</b>، <b>رشته‌کوه‌ها</b>، دریاها و <b>گلوگاه‌های</b> کلیدی جهان مثل هرمز و سوئز دیده می‌شوند. وقتی اختلالی فعال باشد گلوگاه قرمز می‌تپد.</li><li><b>ساختمان‌هایی</b> که می‌سازید روی خاک کشور خودتان نشانگر می‌شوند: حلقهٔ تپنده با کمان پیشرفت در حین ساخت و نشان پُر پس از اتمام. با رفتن یا کلیک روی نشانگر می‌بینید چیست.</li></ul><p>دکمهٔ گزینه‌ها (آیکن لغزنده) نمایش نام‌ها، شهرها، عوارض طبیعی، مسیرهای تجارت و نشانگر ساختمان‌ها را روشن/خاموش می‌کند.</p>` } },
{ t: { en: "Map layers & legend", fa: "لایه‌های نقشه و راهنمای رنگ" }, b: {
  en: `<p>The <b>Layer</b> menu in the top-left of the map recolours every country:</p><ul><li><b>Political</b> – blocs (West, East, Non-aligned); you are teal.</li><li><b>Relations</b> – how each nation feels about you.</li><li><b>GDP / GDP per person</b> – economic size and wealth.</li><li><b>Stability</b> and <b>Technology</b>.</li><li><b>Trade balance</b> – surplus (green) or deficit (red).</li><li><b>Production</b> and <b>Net exports</b> – for the commodity you choose (oil, gas, grain, chips…). Green countries export, red ones import.</li></ul><p>The legend at the bottom-right explains the colours. Hovering any country shows its value for the active layer.</p>`,
  fa: `<p>منوی <b>لایه</b> در گوشهٔ بالا-چپ نقشه، رنگ همهٔ کشورها را تغییر می‌دهد:</p><ul><li><b>سیاسی</b> – بلوک‌ها (غرب، شرق، غیرمتعهد)؛ شما فیروزه‌ای هستید.</li><li><b>روابط</b> – نظر هر کشور دربارهٔ شما.</li><li><b>تولید ناخالص / سرانه</b> – اندازه و ثروت اقتصادی.</li><li><b>ثبات</b> و <b>فناوری</b>.</li><li><b>تراز تجاری</b> – مازاد (سبز) یا کسری (قرمز).</li><li><b>تولید</b> و <b>صادرات خالص</b> – برای کالایی که انتخاب می‌کنید (نفت، گاز، غلات، تراشه …). کشورهای سبز صادر می‌کنند و قرمزها وارد.</li></ul><p>راهنمای رنگ در پایین-راست معنی رنگ‌ها را می‌گوید. با نگه‌داشتن ماوس روی هر کشور مقدار آن برای لایهٔ فعال نشان داده می‌شود.</p>` } },
{ t: { en: "Top bar, time & shortcuts", fa: "نوار بالا، زمان و میانبرها" }, b: {
  en: `<p>The top bar shows the date and your key numbers: treasury, GDP, monthly balance, inflation, approval and population.</p><h4>Controls (bottom bar)</h4><ul><li><b>Advance month</b> – simulate one month.</li><li><b>Play / pause</b> – auto-play at 1×, 2× or 4×. It pauses by itself when a decision is waiting for you.</li></ul><h4>Shortcuts</h4><ul><li><b>Space</b> advance · <b>P</b> play/pause · <b>M</b> mute · <b>+ / −</b> zoom · <b>Esc</b> close card, panel or window.</li></ul><p>The game autosaves after each month (can be turned off in Settings). The <b>Save</b> button saves instantly.</p>`,
  fa: `<p>نوار بالا تاریخ و اعداد کلیدی شما را نشان می‌دهد: خزانه، تولید ناخالص، تراز ماهانه، تورم، رضایت و جمعیت.</p><h4>کنترل‌ها (نوار پایین)</h4><ul><li><b>ماه بعد</b> – یک ماه را شبیه‌سازی می‌کند.</li><li><b>پخش / توقف</b> – پخش خودکار با سرعت ۱×، ۲× یا ۴×. وقتی تصمیمی منتظر شماست خودش متوقف می‌شود.</li></ul><h4>میانبرها</h4><ul><li><b>Space</b> ماه بعد · <b>P</b> پخش/توقف · <b>M</b> بی‌صدا · <b>+ / −</b> زوم · <b>Esc</b> بستن کارت، پنل یا پنجره.</li></ul><p>بازی بعد از هر ماه خودکار ذخیره می‌شود (در تنظیمات قابل خاموش‌کردن است). دکمهٔ <b>ذخیره</b> فوراً ذخیره می‌کند.</p>` } },
{ t: { en: "Overview panel", fa: "پنل نمای کلی" }, b: {
  en: `<p>Your dashboard: GDP and world rank, treasury and debt, population, approval and stability.</p><ul><li><b>Indicators</b> – education, health, infrastructure, technology, environment, defence, internet and food security (0–100).</li><li><b>Resources</b> – energy, fresh water, food and raw materials. These now depend on real supply from the global market and your own production. Below 30 they hurt satisfaction and raise inflation.</li><li><b>World powers</b> – the biggest economies. Click a row to jump to that country.</li></ul>`,
  fa: `<p>داشبورد شما: تولید ناخالص و رتبهٔ جهانی، خزانه و بدهی، جمعیت، رضایت و ثبات.</p><ul><li><b>شاخص‌ها</b> – آموزش، سلامت، زیرساخت، فناوری، محیط زیست، دفاع، اینترنت و امنیت غذایی (۰ تا ۱۰۰).</li><li><b>منابع</b> – انرژی، آب شیرین، غذا و مواد خام. این‌ها اکنون به عرضهٔ واقعی بازار جهانی و تولید خودتان بستگی دارند. زیر ۳۰ به رضایت آسیب می‌زنند و تورم را بالا می‌برند.</li><li><b>قدرت‌های جهان</b> – بزرگ‌ترین اقتصادها. روی یک ردیف کلیک کنید تا به آن کشور بروید.</li></ul>` } },
{ t: { en: "Economy & budget", fa: "اقتصاد و بودجه" }, b: {
  en: `<p>Each month: <b>revenue</b> (taxes, tariffs, a share of exports, buildings) minus <b>expenses</b> (subsidies, investment, defence, environment, debt interest) gives the <b>balance</b>.</p><ul><li>If the treasury would go negative the state borrows automatically and debt grows. Debt above ~150–180% of GDP hurts stability.</li><li><b>Repay debt</b> uses up to half the treasury.</li><li><b>Policies</b> – taxes, subsidies, investment, defence and environment spending levels.</li><li><b>Inflation</b> rises with shortages, price spikes, high tariffs and deficits, and slowly returns to normal.</li></ul><p>Growth depends on your base growth, factories, technology, trade terms (exporters gain when prices rise, importers lose) and inflation. Charts show the trend.</p>`,
  fa: `<p>هر ماه: <b>درآمد</b> (مالیات، تعرفه، سهمی از صادرات، ساختمان‌ها) منهای <b>هزینه‌ها</b> (یارانه، سرمایه‌گذاری، دفاع، محیط زیست، بهرهٔ بدهی) <b>تراز</b> را می‌دهد.</p><ul><li>اگر خزانه منفی شود دولت خودکار وام می‌گیرد و بدهی بالا می‌رود. بدهی بالای حدود ۱۵۰ تا ۱۸۰٪ تولید ناخالص به ثبات آسیب می‌زند.</li><li><b>بازپرداخت بدهی</b> تا نیمی از خزانه را مصرف می‌کند.</li><li><b>سیاست‌ها</b> – سطح مالیات، یارانه، سرمایه‌گذاری، دفاع و محیط زیست.</li><li><b>تورم</b> با کمبود، جهش قیمت، تعرفهٔ بالا و کسری بالا می‌رود و آهسته به حالت عادی برمی‌گردد.</li></ul><p>رشد به رشد پایه، کارخانه‌ها، فناوری، شرایط تجارت (صادرکننده‌ها با گران‌شدن قیمت سود می‌برند و واردکننده‌ها ضرر می‌کنند) و تورم بستگی دارد. نمودارها روند را نشان می‌دهند.</p>` } },
{ t: { en: "Construction", fa: "ساخت‌وساز" }, b: {
  en: `<p>Eleven building types. Each costs money and raw materials, takes some months and is shown on the map:</p><ul><li><b>Power plant</b> – energy supply. <b>Oil field</b> – oil and gas output. <b>Mine</b> – copper, lithium, rare earths, coal. <b>Agri complex</b> – grain. <b>Factory</b> – steel, chips and growth. <b>Port</b> – cheaper, better trade routes.</li><li><b>School, hospital, road, water, internet</b> – education, health, infrastructure, fresh water, connectivity.</li></ul><p>The queue shows progress. Costs scale with your economy so every nation faces similar relative choices. Mods can change costs or add new buildings.</p>`,
  fa: `<p>یازده نوع ساختمان. هر کدام پول و مواد خام می‌خواهد، چند ماه طول می‌کشد و روی نقشه نشان داده می‌شود:</p><ul><li><b>نیروگاه</b> – عرضهٔ انرژی. <b>میدان نفتی</b> – تولید نفت و گاز. <b>معدن</b> – مس، لیتیوم، خاکی‌های کمیاب، زغال‌سنگ. <b>مجتمع کشاورزی</b> – غلات. <b>کارخانه</b> – فولاد، تراشه و رشد. <b>بندر</b> – مسیرهای تجاری ارزان‌تر و بهتر.</li><li><b>مدرسه، بیمارستان، جاده، آب، اینترنت</b> – آموزش، سلامت، زیرساخت، آب شیرین، ارتباطات.</li></ul><p>صف ساخت پیشرفت را نشان می‌دهد. هزینه‌ها با اقتصاد شما مقیاس می‌شوند تا هر کشور انتخاب‌های نسبی مشابهی داشته باشد. مودها می‌توانند هزینه‌ها را تغییر دهند یا ساختمان تازه اضافه کنند.</p>` } },
{ t: { en: "The global market", fa: "بازار جهانی" }, b: {
  en: `<p>Nine commodities are traded worldwide: <b>oil, gas, coal, grain, steel, copper, lithium, rare earths and chips</b>. Every country (and an aggregated "rest of the world") produces and consumes them using real-world-based shares.</p><h4>How prices form</h4><p>Each month world supply and world demand are added up. Shortage pushes the price up, surplus pushes it down; high prices slowly raise supply and cut demand. Prices drift back to long-run levels unless shocked.</p><h4>How trade flows</h4><p>Importers buy from exporters. Who sells to whom depends on distance, blocs, tariffs, embargoes, pacts and relations. Select a commodity and its main trade routes are animated on the map.</p><h4>Events</h4><p>Wars of words, droughts, strikes, export controls and recessions create <b>shocks</b> (supply or demand multipliers for a number of months). Active shocks are listed in the panel.</p>`,
  fa: `<p>نه کالا در جهان معامله می‌شود: <b>نفت، گاز، زغال‌سنگ، غلات، فولاد، مس، لیتیوم، خاکی‌های کمیاب و تراشه</b>. هر کشور (و یک «سایر جهان» تجمیعی) آن‌ها را با سهم‌هایی بر پایهٔ دنیای واقعی تولید و مصرف می‌کند.</p><h4>قیمت چگونه شکل می‌گیرد</h4><p>هر ماه عرضه و تقاضای جهانی جمع زده می‌شود. کمبود قیمت را بالا می‌برد و مازاد پایین می‌آورد؛ قیمت بالا آرام‌آرام عرضه را زیاد و تقاضا را کم می‌کند. بدون شوک، قیمت‌ها به سطح بلندمدت برمی‌گردند.</p><h4>تجارت چگونه جریان می‌یابد</h4><p>واردکننده‌ها از صادرکننده‌ها می‌خرند. اینکه چه کسی به چه کسی بفروشد به فاصله، بلوک‌ها، تعرفه‌ها، تحریم‌ها، پیمان‌ها و روابط بستگی دارد. با انتخاب یک کالا، مسیرهای اصلی تجارت آن روی نقشه متحرک نشان داده می‌شود.</p><h4>رویدادها</h4><p>تنش‌ها، خشکسالی، اعتصاب، کنترل صادرات و رکود <b>شوک</b> می‌سازند (ضریب عرضه یا تقاضا برای چند ماه). شوک‌های فعال در پنل فهرست می‌شوند.</p>` } },
{ t: { en: "Trading, tariffs & reserves", fa: "تجارت، تعرفه و ذخایر" }, b: {
  en: `<p>In the <b>Global market</b> panel pick a commodity from the list.</p><ul><li><b>Your position</b> – production, consumption, imports, exports and reserve (months of cover). The supply bar must stay near 100%; below that you have a shortage.</li><li><b>Tariff</b> – import tax for this commodity (or for everything). Tariffs earn revenue and protect, but make foreign supply less attractive, raise inflation and make partners cool toward you if you go above ~15% on average.</li><li><b>Export ban</b> – keeps your production at home (it piles up in reserves). Useful in a crisis; it removes your export income.</li><li><b>Spot trade</b> – buy or sell a share (5–50%) of a month's national consumption at the market price. Buying fills the reserve (up to 12 months) and costs price + tariff + 3%; selling pays price − 3%.</li></ul><p>Reserves are used automatically when imports and production fall short, which protects your resource gauges.</p>`,
  fa: `<p>در پنل <b>بازار جهانی</b> یک کالا را از فهرست انتخاب کنید.</p><ul><li><b>وضعیت شما</b> – تولید، مصرف، واردات، صادرات و ذخیره (ماه‌های پوشش). نوار عرضه باید نزدیک ۱۰۰٪ بماند؛ پایین‌تر یعنی کمبود.</li><li><b>تعرفه</b> – مالیات واردات این کالا (یا همهٔ کالاها). تعرفه درآمد دارد و حمایت می‌کند، اما تأمین خارجی را کم‌جذاب می‌کند، تورم را بالا می‌برد و اگر میانگین از حدود ۱۵٪ بالاتر برود شرکا نسبت به شما سرد می‌شوند.</li><li><b>ممنوعیت صادرات</b> – تولید شما را در داخل نگه می‌دارد (در ذخایر انباشته می‌شود). در بحران مفید است؛ درآمد صادراتی را حذف می‌کند.</li><li><b>معامله نقدی</b> – بخشی (۵ تا ۵۰٪) از مصرف یک ماههٔ ملی را به قیمت بازار بخرید یا بفروشید. خرید ذخیره را پر می‌کند (تا ۱۲ ماه) و هزینه‌اش قیمت + تعرفه + ۳٪ است؛ فروش قیمت − ۳٪ می‌پردازد.</li></ul><p>وقتی واردات و تولید کم بیاید، ذخایر خودکار مصرف می‌شوند و شاخص‌های منابع را محافظت می‌کنند.</p>` } },
{ t: { en: "Resources & shortages", fa: "منابع و کمبودها" }, b: {
  en: `<p>The four gauges follow the market: <b>energy</b> (oil, gas, coal), <b>food</b> (grain), <b>raw materials</b> (steel, copper) and <b>fresh water</b> (from water projects). Chips feed technology; lithium and rare earths feed industry and prices.</p><p>When supply covers demand the gauges settle near 70. Shortages push them down, and low gauges reduce approval and raise inflation. Construction consumes raw materials, so keep an eye on them. Building power plants, farms, mines and factories raises your own production and gauges.</p>`,
  fa: `<p>چهار شاخص از بازار پیروی می‌کنند: <b>انرژی</b> (نفت، گاز، زغال‌سنگ)، <b>غذا</b> (غلات)، <b>مواد خام</b> (فولاد، مس) و <b>آب شیرین</b> (از پروژه‌های آب). تراشه به فناوری کمک می‌کند؛ لیتیوم و خاکی‌های کمیاب به صنعت و قیمت‌ها.</p><p>وقتی عرضه تقاضا را پوشش دهد شاخص‌ها نزدیک ۷۰ می‌مانند. کمبود آن‌ها را پایین می‌کشد و شاخص پایین رضایت را کم و تورم را زیاد می‌کند. ساخت‌وساز مواد خام مصرف می‌کند، پس حواستان به آن باشد. ساخت نیروگاه، مزرعه، معدن و کارخانه تولید و شاخص‌های خودتان را بالا می‌برد.</p>` } },
{ t: { en: "Population & infrastructure", fa: "جمعیت و زیرساخت" }, b: {
  en: `<p><b>Population</b> grows with health and satisfaction. Education, health and internet indices improve through schools, hospitals and internet projects and decay slowly without them.</p><p><b>Infrastructure</b> combines roads, ports, power, water and connectivity. Good infrastructure helps food security, regional development and trade.</p>`,
  fa: `<p><b>جمعیت</b> با سلامت و رضایت رشد می‌کند. شاخص‌های آموزش، سلامت و اینترنت با مدرسه، بیمارستان و پروژه‌های اینترنت بهتر می‌شوند و بدون آن‌ها آهسته افت می‌کنند.</p><p><b>زیرساخت</b> ترکیب جاده، بندر، برق، آب و ارتباطات است. زیرساخت خوب به امنیت غذایی، توسعهٔ منطقه‌ها و تجارت کمک می‌کند.</p>` } },
{ t: { en: "Diplomacy", fa: "دیپلماسی" }, b: {
  en: `<p>Click any country (map or Diplomacy panel) for actions:</p><ul><li><b>Summit</b> – small relation gain, free.</li><li><b>Trade pact</b> – removes tariffs both ways and makes trade much easier (needs relation above −20).</li><li><b>Research exchange</b> – slow technology gains (needs relation 10+).</li><li><b>Aid</b> – costs money, +12 relation.</li><li><b>Embargo</b> – stops all trade with that country and sours relations; lift it later to recover.</li></ul><p>Relations drift back toward a natural level set by blocs. High tariffs on others provoke retaliation. Relation also scales how attractive you are as a trading partner.</p>`,
  fa: `<p>روی هر کشور (نقشه یا پنل دیپلماسی) کلیک کنید تا اقدامات را ببینید:</p><ul><li><b>نشست سران</b> – افزایش اندک روابط، رایگان.</li><li><b>پیمان تجاری</b> – تعرفه‌ها را دوطرفه حذف می‌کند و تجارت را آسان‌تر می‌کند (روابط باید بالاتر از ۲۰- باشد).</li><li><b>تبادل پژوهشی</b> – رشد آهستهٔ فناوری (روابط ۱۰ به بالا).</li><li><b>کمک مالی</b> – هزینه دارد، ۱۲+ روابط.</li><li><b>تحریم</b> – همهٔ تجارت با آن کشور را قطع می‌کند و روابط را خراب می‌کند؛ بعداً با برداشتن آن بهبود می‌یابد.</li></ul><p>روابط به‌تدریج به سطح طبیعی تعیین‌شده توسط بلوک‌ها برمی‌گردند. تعرفهٔ بالا بر دیگران تلافی برمی‌انگیزد. روابط همچنین جذابیت شما را به‌عنوان شریک تجاری تغییر می‌دهد.</p>` } },
{ t: { en: "Politics, security & environment", fa: "سیاست، امنیت و محیط زیست" }, b: {
  en: `<p><b>Politics</b> – four parties share support. Hold an <b>election</b> (result depends on approval and stability), pass a <b>reform</b> or open <b>dialogue</b> to calm tensions.</p><p><b>Security</b> – military drills raise defence; patrols raise stability. <b>Environment</b> – restoration raises the environment index; regulation helps it slowly but costs a little output. Factories lower it, environment spending raises it.</p>`,
  fa: `<p><b>سیاست</b> – چهار حزب حمایت را بین خود تقسیم می‌کنند. <b>انتخابات</b> برگزار کنید (نتیجه به رضایت و ثبات بستگی دارد)، <b>اصلاحات</b> تصویب کنید یا با <b>گفت‌وگو</b> تنش‌ها را آرام کنید.</p><p><b>امنیت</b> – رزمایش دفاع را بالا می‌برد؛ گشت ثبات را. <b>محیط زیست</b> – بازسازی شاخص را بالا می‌برد؛ مقررات آهسته کمک می‌کند ولی کمی از تولید می‌کاهد. کارخانه‌ها آن را پایین می‌آورند و هزینهٔ محیط زیست بالا می‌برد.</p>` } },
{ t: { en: "Military & conquest", fa: "ارتش و تصرف قلمرو" }, b: {
  en: `<p>You can build an army, fight wars and take other nations' land. Everything is conventional — there are no nuclear weapons. Open the <b>Military</b> panel (crossed-swords icon).</p><h4>Command, Forces and Technology</h4><ul><li><b>Command</b> – personnel, readiness, air defence, upkeep, your world military rank and active wars.</li><li><b>Forces</b> – build infantry, armored brigades, artillery, fighters, bombers, combat drones, corvettes, destroyers, amphibious transports, submarines, carriers, air-defence batteries and a missile shield, plus four missile types (short-range ballistic, cruise, long-range ballistic, hypersonic). Orders take months and cost upkeep. Your population limits the size of your army.</li><li><b>Technology</b> – a tree of 18 military technologies. Some need other military techs, and a few also need a civilian technology (drones and the missile shield need AI; stealth and hypersonics need advanced materials).</li></ul><h4>Every nation has a military</h4><p>Click a country: its card shows military rating, troops and air defence. In the <b>War room</b> you also see its air force, navy, missile arsenal, readiness and the condition (0–100%) of seven key targets: bases, airfields, air-defence network, power grid, industry, ports and command &amp; control.</p><h4>How to reach a target</h4><ul><li><b>By land</b> – only along real borders; through at most two other countries.</li><li><b>By sea</b> – for islands and distant coasts: you need <b>amphibious transports</b> (each carries 2 divisions), and your fleet must win <b>sea control</b>. Landlocked nations (Kazakhstan, Mongolia, Bolivia, Ethiopia) cannot be invaded by sea.</li><li><b>By air / missile</b> – limited by range; missiles and aircraft cross the airspace of other nations on the way.</li></ul><h4>Permissions</h4><p>Crossing a third country needs its <b>airspace</b> permission (aircraft, missiles) or <b>passage</b> permission (armies). Ask in the War room or the Access tab. Acceptance depends on relations, trade pacts, embargoes and whether the target is in that nation's bloc. Permits last 12 months. You can ignore permissions, but that causes incidents and relations collapse.</p><h4>Fighting a war</h4><ol><li><b>Declare war</b> (max two at once). If relations were friendly it is unjustified and the world turns against you.</li><li><b>Missile strikes</b> and <b>air operations</b> damage a chosen target category. Air defence intercepts part of every strike, aircraft can be shot down, and missiles are used up.</li><li><b>Ground offensive</b> – commit a share of your army by land or sea. Each month the battle is decided by force ratio, quality, air superiority, terrain, readiness and the defender's mobilisation. Big countries take longer to conquer.</li><li>The enemy fights back: ground counter-offensives, and missile strikes that can <b>destroy your buildings</b> (they vanish from the map). Air defence and fortification reduce the damage.</li><li>War costs upkeep, hurts growth and approval, and builds <b>war weariness</b>. Both sides eventually accept a <b>ceasefire</b>.</li></ol><h4>After a victory</h4><p>At 100% conquest you choose: <b>annex</b> (their land, people and economy become yours, with unrest and world anger), install a <b>friendly government</b> (stays independent, joins your bloc), or demand <b>reparations</b> (12% of its GDP). Annexed land turns your colour on the map.</p><p>Hostile, stronger neighbours may attack you too — keep your defence up.</p>`,
  fa: `<p>می‌توانید ارتش بسازید، جنگ کنید و قلمرو دیگران را بگیرید. همه‌چیز متعارف است — سلاح هسته‌ای وجود ندارد. پنل <b>ارتش</b> (آیکن شمشیرهای متقاطع) را باز کنید.</p><h4>فرماندهی، یگان‌ها و فناوری</h4><ul><li><b>فرماندهی</b> – نیروی انسانی، آمادگی، پدافند هوایی، هزینهٔ نگهداری، رتبهٔ نظامی شما در جهان و جنگ‌های فعال.</li><li><b>یگان‌ها</b> – لشکر پیاده، تیپ زرهی، توپخانه، جنگنده، بمب‌افکن، پهپاد رزمی، ناوچه، ناوشکن، ناو ترابری آبی‌خاکی، زیردریایی، ناو هواپیمابر، آتشبار پدافند و سپر موشکی، به‌علاوهٔ چهار نوع موشک (بالستیک کوتاه‌برد، کروز، بالستیک دوربرد، مافوق‌صوت). سفارش‌ها چند ماه طول می‌کشد و هزینهٔ نگهداری دارند. جمعیت، اندازهٔ ارتش را محدود می‌کند.</li><li><b>فناوری</b> – درختی از ۱۸ فناوری نظامی. بعضی به فناوری نظامی دیگر نیاز دارند و چند تا به فناوری غیرنظامی هم (پهپاد و سپر موشکی به هوش مصنوعی؛ رادارگریز و مافوق‌صوت به مواد پیشرفته).</li></ul><h4>هر کشور ارتش دارد</h4><p>روی یک کشور کلیک کنید: کارتش رتبهٔ نظامی، سرباز و پدافند را نشان می‌دهد. در <b>اتاق جنگ</b> نیروی هوایی، ناوگان، زرادخانهٔ موشکی، آمادگی و وضعیت (۰ تا ۱۰۰٪) هفت هدف کلیدی را هم می‌بینید: پایگاه‌ها، فرودگاه‌ها، شبکهٔ پدافند، شبکهٔ برق، صنعت، بنادر و فرماندهی و کنترل.</p><h4>چگونه به هدف برسیم</h4><ul><li><b>زمینی</b> – فقط از مرزهای واقعی؛ حداکثر از میان دو کشور دیگر.</li><li><b>دریایی</b> – برای جزیره‌ها و سواحل دور: به <b>ناو ترابری آبی‌خاکی</b> نیاز دارید (هر کدام ۲ لشکر می‌برد) و ناوگان باید <b>کنترل دریا</b> را بگیرد. کشورهای بدون ساحل (قزاقستان، مغولستان، بولیوی، اتیوپی) از دریا قابل حمله نیستند.</li><li><b>هوایی / موشکی</b> – محدود به برد؛ موشک و هواپیما در مسیر از حریم هوایی کشورهای دیگر می‌گذرند.</li></ul><h4>مجوزها</h4><p>عبور از کشور ثالث به مجوز <b>حریم هوایی</b> (هواپیما و موشک) یا مجوز <b>عبور زمینی</b> (ارتش) نیاز دارد. در اتاق جنگ یا زبانهٔ مجوزها درخواست کنید. پذیرش به روابط، پیمان تجاری، تحریم‌ها و اینکه هدف هم‌بلوک آن کشور باشد بستگی دارد. مجوزها ۱۲ ماه معتبرند. می‌توانید مجوز را نادیده بگیرید، ولی حادثه می‌سازد و روابط فرو می‌ریزد.</p><h4>جنگیدن</h4><ol><li><b>اعلام جنگ</b> (حداکثر دو جنگ هم‌زمان). اگر روابط دوستانه بود ناموجه است و جهان علیه شما می‌شود.</li><li><b>حملهٔ موشکی</b> و <b>عملیات هوایی</b> یک دستهٔ هدف را آسیب می‌زنند. پدافند بخشی از هر حمله را رهگیری می‌کند، هواپیما ممکن است ساقط شود و موشک‌ها مصرف می‌شوند.</li><li><b>تهاجم زمینی</b> – بخشی از ارتش را زمینی یا دریایی وارد نبرد کنید. هر ماه نتیجه با نسبت نیرو، کیفیت، برتری هوایی، زمین، آمادگی و بسیج مدافع تعیین می‌شود. کشورهای بزرگ دیرتر فتح می‌شوند.</li><li>دشمن جواب می‌دهد: ضدحملهٔ زمینی و حملهٔ موشکی که می‌تواند <b>ساختمان‌های شما را نابود کند</b> (از نقشه محو می‌شوند). پدافند و استحکامات خسارت را کم می‌کنند.</li><li>جنگ هزینهٔ نگهداری دارد، به رشد و رضایت آسیب می‌زند و <b>خستگی از جنگ</b> می‌سازد. هر دو طرف سرانجام <b>آتش‌بس</b> را می‌پذیرند.</li></ol><h4>بعد از پیروزی</h4><p>در ۱۰۰٪ تصرف انتخاب می‌کنید: <b>الحاق</b> (خاک، مردم و اقتصادشان مال شما می‌شود، با ناآرامی و خشم جهانی)، برقراری <b>دولت دوست</b> (مستقل می‌ماند و به بلوک شما می‌پیوندد) یا گرفتن <b>غرامت</b> (۱۲٪ تولید ناخالصش). خاک الحاق‌شده روی نقشه به رنگ شما درمی‌آید.</p><p>همسایگان قوی‌تر و خصمانه ممکن است به شما هم حمله کنند — دفاعتان را بالا نگه دارید.</p>` } },
{ t: { en: "Research", fa: "تحقیقات" }, b: {
  en: `<p>Six technologies: renewables (energy), AI (technology), medicine (health), automation (industry and growth), water systems and advanced materials. One project at a time; it costs money up front and finishes after a set number of months, granting a one-off boost. Research partners from diplomacy give slow technology growth.</p>`,
  fa: `<p>شش فناوری: انرژی تجدیدپذیر (انرژی)، هوش مصنوعی (فناوری)، پزشکی (سلامت)، خودکارسازی (صنعت و رشد)، سامانه‌های آب و مواد پیشرفته. هر بار یک پروژه؛ هزینه از ابتدا پرداخت می‌شود و پس از چند ماه تمام می‌شود و یک تقویت یک‌باره می‌دهد. شرکای پژوهشی از دیپلماسی رشد آهستهٔ فناوری می‌دهند.</p>` } },
{ t: { en: "Regions", fa: "منطقه‌ها" }, b: {
  en: `<p>Your nation has four regions. Each has a development level and a specialisation. Investing raises development, and good infrastructure lifts all regions over time.</p>`,
  fa: `<p>کشور شما چهار منطقه دارد. هر کدام سطح توسعه و تخصصی دارد. سرمایه‌گذاری توسعه را بالا می‌برد و زیرساخت خوب با گذر زمان همهٔ منطقه‌ها را بالا می‌کشد.</p>` } },
{ t: { en: "Events & decisions", fa: "رویدادها و تصمیم‌ها" }, b: {
  en: `<p>Most turns nothing special happens, but regularly a <b>world event</b> (a Gulf crisis, a drought, a chip shortage…) or a <b>domestic event</b> appears and the dock icon shows a badge. Each offers choices with real costs and consequences. The same event also changes the market for everyone, whatever you choose. Undecided events expire after eight months with a small penalty. Auto-play stops when something needs a decision.</p>`,
  fa: `<p>در بیشتر ماه‌ها اتفاق ویژه‌ای نمی‌افتد، اما گاه‌به‌گاه یک <b>رویداد جهانی</b> (بحران خلیج، خشکسالی، کمبود تراشه …) یا <b>رویداد داخلی</b> ظاهر می‌شود و آیکن منو نشان می‌گیرد. هر کدام گزینه‌هایی با هزینه و پیامد واقعی دارد. همان رویداد بازار را برای همه عوض می‌کند، هر چه انتخاب کنید. رویدادهای بی‌تصمیم پس از هشت ماه با جریمهٔ کوچک منقضی می‌شوند. پخش خودکار وقتی تصمیمی لازم باشد متوقف می‌شود.</p>` } },
{ t: { en: "Scenarios & objectives", fa: "سناریوها و اهداف" }, b: {
  en: `<p>A scenario sets the starting date, prices, tariffs and scheduled shocks:</p><ul><li><b>Modern World 2026</b> – the standard game.</li><li><b>Energy Crisis</b> – oil and gas prices are very high.</li><li><b>Global Trade War</b> – tariffs everywhere.</li><li><b>Debt Crisis</b> – recession and heavy debt.</li><li><b>Green Transition 2030</b> – lithium, copper and rare earths boom.</li><li><b>Food Crisis</b> – a grain shortage.</li><li><b>Chip & Mineral Race</b> – chips and rare earths are scarce.</li></ul><p>Each scenario has three <b>objectives</b> (GDP growth, low inflation for N months, stability, buildings, research, pacts, technology…) tracked in the Scenario panel. Completing all of them wins the scenario; you may keep playing.</p>`,
  fa: `<p>سناریو تاریخ شروع، قیمت‌ها، تعرفه‌ها و شوک‌های برنامه‌ریزی‌شده را تعیین می‌کند:</p><ul><li><b>جهان امروز ۲۰۲۶</b> – بازی استاندارد.</li><li><b>بحران انرژی</b> – قیمت نفت و گاز بسیار بالاست.</li><li><b>جنگ تجاری جهانی</b> – تعرفه در همه‌جا.</li><li><b>بحران بدهی</b> – رکود و بدهی سنگین.</li><li><b>گذار سبز ۲۰۳۰</b> – رونق لیتیوم، مس و خاکی‌های کمیاب.</li><li><b>بحران غذا</b> – کمبود غلات.</li><li><b>رقابت تراشه و مواد معدنی</b> – تراشه و خاکی‌های کمیاب کمیابند.</li></ul><p>هر سناریو سه <b>هدف</b> دارد (رشد تولید ناخالص، تورم پایین برای چند ماه، ثبات، ساختمان، تحقیق، پیمان، فناوری …) که در پنل سناریو دنبال می‌شود. تکمیل همه، سناریو را می‌برد؛ می‌توانید ادامه دهید.</p>` } },
{ t: { en: "Mods", fa: "مودها" }, b: {
  en: `<p>Mods change the rules. Six come built in (Green Future, Resource Scarcity, Hard Economy, Free Trade Era, Tech Boom, Pacific Century). Choose mods when creating a world, or toggle them any time in the <b>Mods</b> panel (country-statistics patches only apply at creation).</p><h4>Your own mods</h4><p>A mod is a JSON file. Use <b>Import mod</b> (main screen or Mods panel) or put the file in the mods folder. Everything is validated and clamped, so a broken mod cannot break the game. Mods can: patch countries, change production, shift commodity demand, change building costs, add new buildings, change global rules and add events with choices and market shocks. A full example is shown in the Mods panel.</p>`,
  fa: `<p>مودها قوانین را تغییر می‌دهند. شش مود آماده است (آینده سبز، کمبود منابع، اقتصاد سخت، عصر تجارت آزاد، رونق فناوری، قرن اقیانوس آرام). مودها را هنگام ساخت جهان انتخاب کنید یا هر زمان در پنل <b>مودها</b> روشن/خاموش کنید (تغییر آمار کشورها فقط هنگام ساخت اعمال می‌شود).</p><h4>مودهای خودتان</h4><p>مود یک فایل JSON است. از <b>وارد کردن مود</b> (صفحهٔ اصلی یا پنل مودها) استفاده کنید یا فایل را در پوشهٔ مودها بگذارید. همه‌چیز اعتبارسنجی و محدود می‌شود، پس مود خراب بازی را نمی‌شکند. مودها می‌توانند: آمار کشورها را تغییر دهند، تولید را عوض کنند، تقاضای کالاها را جابه‌جا کنند، هزینهٔ ساختمان‌ها را تغییر دهند، ساختمان تازه اضافه کنند، قوانین جهانی را عوض کنند و رویداد با گزینه و شوک بازار بیفزایند. نمونهٔ کامل در پنل مودها نشان داده شده است.</p>` } },
{ t: { en: "Sound & your own music", fa: "صدا و موسیقی شخصی" }, b: {
  en: `<p>The game has interface sounds and a calm generated ambience (no downloads). In <b>Settings → Audio</b> adjust master, effects, ambience and music volume, or mute everything (M).</p><h4>Your music</h4><p>In <b>Settings → Your music</b> press <b>Add music files</b> and choose MP3, OGG, WAV, M4A, FLAC or similar. Your list is remembered. Use play/pause, stop, previous and next, tick Loop or Shuffle, and remove tracks with ✕. While music plays the ambience becomes quieter.</p>`,
  fa: `<p>بازی صدای رابط و یک فضای آرام تولیدشده دارد (بدون دانلود). در <b>تنظیمات ← صدا</b> بلندی کلی، افکت‌ها، فضا و موسیقی را تنظیم کنید یا همه را بی‌صدا کنید (M).</p><h4>موسیقی شما</h4><p>در <b>تنظیمات ← موسیقی شما</b> روی <b>افزودن فایل موسیقی</b> بزنید و MP3، OGG، WAV، M4A، FLAC یا مشابه را انتخاب کنید. فهرست شما به خاطر سپرده می‌شود. از پخش/مکث، توقف، قبلی و بعدی استفاده کنید، تکرار یا درهم را روشن کنید و آهنگ‌ها را با ✕ حذف کنید. هنگام پخش موسیقی، صدای فضا کمتر می‌شود.</p>` } },
{ t: { en: "Language & text", fa: "زبان و متن" }, b: {
  en: `<p>Switch between English and Persian at any time with the language button (top bar or main screen) or in <b>Settings → Language</b>. Only the text changes: the layout never flips, numbers and dates use the chosen language and the Persian font is used throughout. For the best Persian font run <b>npm install</b> once (it installs Vazirmatn automatically).</p>`,
  fa: `<p>هر زمان با دکمهٔ زبان (نوار بالا یا صفحهٔ اصلی) یا در <b>تنظیمات ← زبان</b> بین فارسی و انگلیسی جابه‌جا شوید. فقط متن‌ها عوض می‌شوند: چیدمان هرگز برعکس نمی‌شود، اعداد و تاریخ‌ها به زبان انتخابی نمایش داده می‌شوند و همه‌جا از فونت فارسی استفاده می‌شود. برای بهترین فونت فارسی یک بار <b>npm install</b> را اجرا کنید (فونت وزیرمتن خودکار نصب می‌شود).</p>` } },
{ t: { en: "Saving, backups & map data", fa: "ذخیره، پشتیبان و داده نقشه" }, b: {
  en: `<p>Autosave runs every month (toggle in Settings). <b>Export</b> downloads your world as a JSON backup; <b>Import</b> restores it as a new save. Saves from the old alpha are converted to a custom island nation.</p><h4>More detailed borders</h4><p>The built-in map uses simplified outlines. To get survey-grade borders, place a Natural Earth <b>world.geojson</b> (with ISO_A3 codes) in the maps folder (Settings → Map data) and restart: the game uses its country shapes automatically.</p>`,
  fa: `<p>ذخیرهٔ خودکار هر ماه انجام می‌شود (در تنظیمات قابل خاموش‌کردن). <b>خروجی</b> جهان شما را به‌صورت پشتیبان JSON دانلود می‌کند و <b>ورودی</b> آن را به‌عنوان ذخیرهٔ تازه بازمی‌گرداند. ذخیره‌های نسخهٔ آلفای قدیمی به یک کشور جزیره‌ای تبدیل می‌شوند.</p><h4>مرزهای دقیق‌تر</h4><p>نقشهٔ داخلی طرح‌های ساده‌شده دارد. برای مرزهای با دقت نقشه‌برداری، فایل <b>world.geojson</b> از Natural Earth (دارای کدهای ISO_A3) را در پوشهٔ نقشه‌ها (تنظیمات ← داده نقشه) بگذارید و بازی را دوباره باز کنید: شکل کشورها خودکار از آن گرفته می‌شود.</p>` } },
{ t: { en: "Strategy tips", fa: "نکات راهبردی" }, b: {
  en: `<ul><li>Check the Global market before building: if you import a commodity heavily, a mine, oil field or farm can be worth more than another factory.</li><li>Keep 2–3 months of reserves of critical goods before a crisis.</li><li>Exporters profit from high prices; importers should diversify partners, sign trade pacts and watch tariffs.</li><li>Do not let inflation sit above 10% – it drags approval and stability.</li><li>Resolve events quickly; the market shock starts immediately anyway.</li><li>Use layers: <i>Net exports</i> for a commodity shows who your rivals and suppliers are.</li></ul>`,
  fa: `<ul><li>قبل از ساخت، بازار جهانی را ببینید: اگر کالایی را زیاد وارد می‌کنید، یک معدن، میدان نفتی یا مزرعه می‌تواند از یک کارخانهٔ دیگر ارزشمندتر باشد.</li><li>پیش از بحران، ۲ تا ۳ ماه ذخیرهٔ کالاهای حیاتی داشته باشید.</li><li>صادرکننده‌ها از قیمت بالا سود می‌برند؛ واردکننده‌ها باید شرکا را متنوع کنند، پیمان تجاری ببندند و مراقب تعرفه‌ها باشند.</li><li>تورم را بالای ۱۰٪ رها نکنید – رضایت و ثبات را می‌کشد.</li><li>رویدادها را سریع تعیین تکلیف کنید؛ شوک بازار به هر حال همان لحظه شروع می‌شود.</li><li>از لایه‌ها استفاده کنید: <i>صادرات خالص</i> یک کالا نشان می‌دهد رقبا و تأمین‌کنندگان شما چه کسانی‌اند.</li></ul>` } }
];

/* ===================== GUIDED PRACTICE ===================== */
const S = (title, text, target, wait, extra = {}) => ({ title, text, target, wait, ...extra });
const B2 = (en, fa) => ({ en, fa });
const STEPS = [
S(B2("Welcome to the practice island", "به جزیرهٔ تمرین خوش آمدید"), B2("This is a safe sandbox world: nothing here is saved. You will do each action for real. Follow the highlighted area and the game waits for you.", "این یک جهان آزمایشی امن است: هیچ‌چیز ذخیره نمی‌شود. هر کار را واقعاً انجام می‌دهید. بخش روشن‌شده را دنبال کنید؛ بازی منتظر شما می‌ماند."), null, "next"),
S(B2("The permanent map", "نقشهٔ دائمی"), B2("The map stays here the whole game. Zoom in with the mouse wheel (or pinch) and drag to move around.", "نقشه در تمام بازی اینجا می‌ماند. با چرخ ماوس (یا دو انگشت) زوم کنید و برای جابه‌جایی بکشید."), "#mapwrap", { ev: "view", test: () => UI.map && UI.map.t.k > UI.map.kMin * 1.5 }, { hint: B2("Waiting: zoom in on the map…", "منتظر: روی نقشه زوم کنید…") }),
S(B2("Pick a country", "یک کشور انتخاب کنید"), B2("Click any country on the map to open its card.", "روی هر کشور نقشه کلیک کنید تا کارت آن باز شود."), "#mapwrap", { ev: "select", test: id => !!id }, { hint: B2("Waiting: click a country…", "منتظر: روی یک کشور کلیک کنید…") }),
S(B2("The country card", "کارت کشور"), B2("Here you see government, population, GDP, stability, technology, trade, and diplomatic buttons (summit, trade pact, research, aid, embargo).", "اینجا نوع حکومت، جمعیت، تولید ناخالص، ثبات، فناوری، تجارت و دکمه‌های دیپلماتیک (نشست، پیمان تجاری، پژوهش، کمک، تحریم) را می‌بینید."), "#countryCard", "next"),
S(B2("Map layers", "لایه‌های نقشه"), B2("Change the Layer menu to recolour the world — try Relations or GDP.", "منوی لایه را تغییر دهید تا نقشه بازرنگ شود — روابط یا تولید ناخالص را امتحان کنید."), "#layerBar", { ev: "layer", test: () => true }, { hint: B2("Waiting: choose another layer…", "منتظر: لایهٔ دیگری انتخاب کنید…") }),
S(B2("Top bar", "نوار بالا"), B2("Date, treasury, GDP, monthly balance, inflation, approval and population are always visible here.", "تاریخ، خزانه، تولید ناخالص، تراز ماهانه، تورم، رضایت و جمعیت همیشه اینجا دیده می‌شود."), "#topbar", "next"),
S(B2("The menu dock", "نوار منوها"), B2("Every management screen is on this dock. Hover an icon to see its name. Panels open beside the map — the map never goes away.", "همهٔ صفحه‌های مدیریتی در این نوار است. روی آیکن‌ها بروید تا نامشان را ببینید. پنل‌ها کنار نقشه باز می‌شوند — نقشه هرگز نمی‌رود."), "#dock", "next"),
S(B2("Open Economy", "اقتصاد را باز کنید"), B2("Click the Economy icon.", "روی آیکن اقتصاد کلیک کنید."), '[data-tab="economy"]', { ev: "tab", test: k => k === "economy" }, { hint: B2("Waiting: open Economy…", "منتظر: اقتصاد را باز کنید…") }),
S(B2("Change a policy", "یک سیاست را تغییر دهید"), B2("Pick a different value for any policy (for example taxes). Higher taxes give more revenue but lower satisfaction over time.", "برای یکی از سیاست‌ها (مثلاً مالیات) مقدار دیگری انتخاب کنید. مالیات بالاتر درآمد بیشتر ولی با گذر زمان رضایت کمتر می‌دهد."), "#panelBody select", { ev: "chg", test: n => n === "policy" }, { hint: B2("Waiting: change a policy value…", "منتظر: مقدار یک سیاست را تغییر دهید…") }),
S(B2("Open Construction", "ساخت‌وساز را باز کنید"), B2("Now click the Construction icon.", "حالا روی آیکن ساخت‌وساز کلیک کنید."), '[data-tab="construction"]', { ev: "tab", test: k => k === "construction" }, { hint: B2("Waiting: open Construction…", "منتظر: ساخت‌وساز را باز کنید…") }),
S(B2("Build something", "چیزی بسازید"), B2("Press Build on a power plant or any affordable project.", "روی «بساز» یک نیروگاه یا هر پروژهٔ قابل‌تأمین بزنید."), "#panelBody [data-act=build].primary", { ev: "build", test: () => true }, { hint: B2("Waiting: start a construction…", "منتظر: یک ساخت‌وساز شروع کنید…") }),
S(B2("See it on the map", "روی نقشه ببینیدش"), B2("Your project now appears on your own island: a pulsing ring with a progress arc. When it is finished it becomes a solid badge. Hover it for its name.", "پروژه‌تان اکنون روی جزیرهٔ خودتان دیده می‌شود: حلقهٔ تپنده با کمان پیشرفت. پس از اتمام به نشان پُر تبدیل می‌شود. برای دیدن نام روی آن بروید."), "#mapwrap", "next", { before: () => UI.map && UI.map.focus(UI.w.playerCountry.id, .12) }),
S(B2("Open the Global market", "بازار جهانی را باز کنید"), B2("Click the globe icon: the global market.", "روی آیکن کره کلیک کنید: بازار جهانی."), '[data-tab="market"]', { ev: "tab", test: k => k === "market" }, { hint: B2("Waiting: open the market…", "منتظر: بازار را باز کنید…") }),
S(B2("Prices", "قیمت‌ها"), B2("Nine commodities with live prices and monthly change. Prices come from world supply and demand.", "نه کالا با قیمت زنده و تغییر ماهانه. قیمت‌ها از عرضه و تقاضای جهانی می‌آیند."), "#panelBody .coms", "next"),
S(B2("Select a commodity", "یک کالا انتخاب کنید"), B2("Click a commodity such as Grain. The chart, supply and demand, your position and trade routes on the map all update.", "روی یک کالا مثل غلات کلیک کنید. نمودار، عرضه و تقاضا، وضعیت شما و مسیرهای تجارت روی نقشه به‌روز می‌شوند."), ".com-row:nth-child(4)", { ev: "com", test: () => true }, { hint: B2("Waiting: select a commodity…", "منتظر: یک کالا انتخاب کنید…") }),
S(B2("Trade on the spot market", "معامله در بازار نقدی"), B2("Press Buy to add a share of a month's consumption to your reserves.", "روی «خرید» بزنید تا بخشی از مصرف یک ماه به ذخایرتان اضافه شود."), "[data-act=spot][data-a=buy]", { ev: "trade", test: () => true }, { hint: B2("Waiting: buy some reserves…", "منتظر: کمی ذخیره بخرید…") }),
S(B2("Tariffs", "تعرفه‌ها"), B2("Set an import tariff for this commodity. Tariffs raise revenue but make foreign supply less attractive.", "یک تعرفهٔ واردات برای این کالا تعیین کنید. تعرفه درآمد می‌آورد ولی تأمین خارجی را کم‌جذاب می‌کند."), "#panelBody select[data-chg=tariff]", { ev: "chg", test: n => n === "tariff" }, { hint: B2("Waiting: change a tariff…", "منتظر: یک تعرفه را تغییر دهید…") }),
S(B2("Diplomacy", "دیپلماسی"), B2("Open Diplomacy to see every nation's attitude. Use summits, trade pacts, research exchange, aid or embargoes — also available from each country card.", "دیپلماسی را باز کنید تا نظر هر کشور را ببینید. از نشست، پیمان تجاری، تبادل پژوهشی، کمک یا تحریم استفاده کنید — از کارت هر کشور هم در دسترس است."), '[data-tab="diplomacy"]', { ev: "tab", test: k => k === "diplomacy" }, { hint: B2("Waiting: open Diplomacy…", "منتظر: دیپلماسی را باز کنید…") }),
S(B2("Military & conquest", "ارتش و تصرف قلمرو"), B2("Open the Military panel: forces, military technology, and the War room where you plan attacks.", "پنل ارتش را باز کنید: یگان‌ها، فناوری نظامی و اتاق جنگ که حمله‌ها را در آن برنامه‌ریزی می‌کنید."), '[data-tab="military"]', { ev: "tab", test: k => k === "military" }, { hint: B2("Waiting: open Military…", "منتظر: ارتش را باز کنید…") }),
S(B2("Forces, war and permissions", "یگان‌ها، جنگ و مجوزها"), B2("Build units and research military tech here. To attack, pick a target in the War room: it shows its forces, the land/sea/air routes and which countries must grant you permission to cross. Then declare war, strike with missiles and aircraft, or commit your army. Annexed land turns your colour.", "اینجا یگان بسازید و فناوری نظامی بیاموزید. برای حمله در اتاق جنگ هدف را انتخاب کنید: نیروهایش، مسیرهای زمینی/دریایی/هوایی و کشورهایی که باید اجازهٔ عبور بدهند نشان داده می‌شود. بعد اعلام جنگ کنید، با موشک و هواپیما بزنید یا ارتشتان را وارد نبرد کنید. خاک الحاق‌شده به رنگ شما درمی‌آید."), "#panelBody", "next"),
S(B2("More departments", "بخش‌های بیشتر"), B2("Politics (parties and elections), Research (technologies), Security, Environment, Regions and Infrastructure follow the same pattern: read, choose, spend. The full guide explains each.", "سیاست (احزاب و انتخابات)، تحقیقات (فناوری‌ها)، امنیت، محیط زیست، منطقه‌ها و زیرساخت همین الگو را دارند: بخوانید، انتخاب کنید، هزینه کنید. راهنمای کامل هر یک را توضیح می‌دهد."), "#dock", "next"),
S(B2("Advance a month", "یک ماه جلو بروید"), B2("Press Advance month. The market updates, your project progresses and events may appear.", "«ماه بعد» را بزنید. بازار به‌روز می‌شود، پروژه‌تان پیش می‌رود و ممکن است رویدادی بیاید."), "#btnAdvance", { ev: "advance", test: () => true }, { hint: B2("Waiting: advance one month…", "منتظر: یک ماه جلو بروید…") }),
S(B2("Auto-play", "پخش خودکار"), B2("Use play for automatic months at 1×, 2× or 4×. It pauses when a decision is needed.", "با پخش، ماه‌ها خودکار می‌گذرند (۱×، ۲× یا ۴×). وقتی تصمیمی لازم باشد متوقف می‌شود."), "#bottombar .speed", "next"),
S(B2("Events", "رویدادها"), B2("When the Events icon shows a badge, a decision is waiting. Each choice has costs and consequences.", "وقتی آیکن رویدادها نشان دارد، تصمیمی منتظر است. هر گزینه هزینه و پیامد دارد."), '[data-tab="events"]', "next"),
S(B2("Scenario & objectives", "سناریو و اهداف"), B2("Track your scenario's three objectives here, plus active market shocks.", "سه هدف سناریو و شوک‌های فعال بازار را اینجا دنبال کنید."), '[data-tab="scenario"]', "next"),
S(B2("Mods", "مودها"), B2("Switch built-in mods on or off, or import your own JSON mod.", "مودهای آماده را روشن/خاموش کنید یا مود JSON خودتان را وارد کنید."), '[data-tab="mods"]', "next"),
S(B2("Settings, language & music", "تنظیمات، زبان و موسیقی"), B2("Switch English/Persian, adjust sound, and add your own music files with play and stop controls.", "زبان فارسی/انگلیسی را عوض کنید، صدا را تنظیم کنید و فایل‌های موسیقی خودتان را با کنترل پخش و توقف اضافه کنید."), '[data-tab="settings"]', "next"),
S(B2("You are ready", "آماده‌اید"), B2("That is the whole loop: read the map and market, build, trade, decide, advance. Return to the menu and start a real world, or keep exploring the sandbox.", "این چرخهٔ کامل بازی است: نقشه و بازار را بخوانید، بسازید، معامله کنید، تصمیم بگیرید، جلو بروید. به منو برگردید و جهان واقعی را شروع کنید یا آزمایشگاه را بیشتر کاوش کنید."), null, "end")
];

/* ---------- coach engine ---------- */
let coach = { i: -1, off: null, poll: null, startK: 0, done: false };
function rectOf(sel) { if (!sel) return null; const el = document.querySelector(sel); if (!el || !el.getClientRects().length) return null; const r = el.getBoundingClientRect(); return r.width < 2 ? null : r; }
function renderCoach() {
  const root = $("#coach"), s = STEPS[coach.i]; if (!s) return; root.classList.remove("hidden");
  const r = rectOf(s.target), pad = 6, W = innerWidth, H = innerHeight, cw = Math.min(340, W - 24);
  const hole = r ? `<div class="coach-hole" style="left:${r.left - pad}px;top:${r.top - pad}px;width:${r.width + pad * 2}px;height:${r.height + pad * 2}px"></div>` : `<div style="position:absolute;inset:0;background:rgba(3,7,10,.66)"></div>`;
  let x = W / 2 - cw / 2, y = H / 2 - 100;
  if (r) { const ch = 210; if (r.right + cw + 24 < W) { x = r.right + 18; y = r.top; } else if (r.left - cw - 24 > 0) { x = r.left - cw - 18; y = r.top; } else { x = r.left; y = r.bottom + 16; } if (y + ch > H) y = Math.max(12, H - ch - 12); x = Math.max(12, Math.min(W - cw - 12, x)); y = Math.max(12, y); }
  const last = coach.i === STEPS.length - 1, waiting = typeof s.wait === "object", pct = (coach.i / (STEPS.length - 1)) * 100;
  const prevCard = root.querySelector(".coach-card"), same = prevCard && prevCard.dataset.i == coach.i;
  root.innerHTML = hole + `<div class="coach-card" data-i="${coach.i}" style="left:${x}px;top:${y}px;width:${cw}px;${same ? "animation:none" : ""}"><div class="coach-prog"><i style="width:${pct}%"></i></div><p class="eyebrow">${t("tut.step", { cur: coach.i + 1, total: STEPS.length })}</p><h4>${esc(X(s.title))}</h4><p>${esc(X(s.text))}</p>${waiting && !coach.done ? `<p class="coach-wait">⏳ ${esc(X(s.hint || { en: "Waiting for your action…", fa: "منتظر اقدام شما…" }))}</p>` : ""}${coach.done ? `<p class="coach-wait">✓ ${t("tut.good")}</p>` : ""}<div class="acts"><button class="chip-btn" data-tut="exit">${t("tut.exit")}</button><div style="display:flex;gap:6px">${coach.i > 0 ? `<button class="chip-btn" data-tut="back">${t("tut.back")}</button>` : ""}${waiting ? `<button class="chip-btn" data-tut="skip">${t("tut.skip")}</button>` : last ? `<button class="primary" data-tut="end">${t("tut.finish")}</button>` : `<button class="primary" data-tut="next">${t("tut.next")}</button>`}</div></div></div>`;
}
function stepTo(i) {
  if (coach.off) { coach.off(); coach.off = null; } coach.done = false; coach.i = Math.max(0, Math.min(STEPS.length - 1, i)); const s = STEPS[coach.i];
  if (s.before) { try { s.before(); } catch {} }
  if (s.wait && typeof s.wait === "object") { const ev = s.wait.ev; coach.off = BUS.on(ev, d => { if (coach.done) return; if (s.wait.test(d)) { coach.done = true; A.play("success"); renderCoach(); setTimeout(() => { if (coach.i >= 0 && STEPS[coach.i] === s) stepTo(coach.i + 1); }, 900); } }); }
  setTimeout(renderCoach, s.target && s.target.includes("panelBody") ? 350 : 60); renderCoach();
}
function startCoach() { coach.i = -1; $("#coach").classList.remove("hidden"); clearInterval(coach.poll); coach.poll = setInterval(() => { if (coach.i >= 0 && !$("#coach").classList.contains("hidden")) renderCoach(); }, 500); stepTo(0); }
function stopCoach() { clearInterval(coach.poll); if (coach.off) { coach.off(); coach.off = null; } coach.i = -1; $("#coach").classList.add("hidden"); $("#coach").innerHTML = ""; }
$("#coach").addEventListener("click", e => {
  const b = e.target.closest("[data-tut]"); if (!b) return; A.play("click"); const k = b.dataset.tut;
  if (k === "next" || k === "skip") stepTo(coach.i + 1); else if (k === "back") stepTo(coach.i - 1); else if (k === "exit") { stopCoach(); UI.backToMenu(); }
  else if (k === "end") { stopCoach(); UI.modal(`<p class="eyebrow">${t("tut.title")}</p><h2>${t("tut.doneTitle")}</h2><p class="desc">${t("tut.doneText")}</p><div class="actions"><button class="ghost" data-act="closeModal">${t("tut.keep")}</button><button class="primary" data-act="menu">${t("tut.toMenu")}</button></div>`); }
});
window.addEventListener("resize", () => { if (coach.i >= 0) renderCoach(); });

/* ---------- overlay with guide + practice launcher ---------- */
let open = false, chIdx = -1, fromGame = false;
function guideHTML() {
  const nav = CH.map((c, i) => `<button data-ch="${i}" class="${i === chIdx ? "on" : ""}"><i>${T.num(i + 1)}</i><span>${esc(X(c.t))}</span></button>`).join("");
  let main;
  if (chIdx < 0) main = `<div><p class="eyebrow">${t("tut.eyebrow")}</p><h2>${t("tut.title")}</h2><p>${t("tut.intro")}</p><div class="tut-hero"><div class="tut-card"><h3>${t("tut.practiceT")}</h3><p>${t("tut.practiceD")}</p><button class="primary big" data-tutact="practice">${t("tut.startPractice")}</button></div><div class="tut-card"><h3>${t("tut.guideT")}</h3><p>${t("tut.guideD", { n: CH.length })}</p><button class="ghost big" data-ch="0">${t("tut.readGuide")}</button></div></div></div>`;
  else { const c = CH[chIdx]; main = `<div><p class="eyebrow">${t("tut.chapter", { cur: chIdx + 1, total: CH.length })}</p><h2>${esc(X(c.t))}</h2>${c.b[L()] || c.b.en}</div>`; }
  const foot = chIdx < 0 ? "" : `<div class="tut-foot"><button class="ghost" data-ch="${chIdx - 1}" ${chIdx === 0 ? "disabled" : ""}>${t("tut.prev")}</button><button class="primary" data-ch="${chIdx + 1 < CH.length ? chIdx + 1 : -1}">${chIdx + 1 < CH.length ? t("tut.nextCh") : t("tut.backHub")}</button></div>`;
  return `<aside class="tut-side"><h3>${t("tut.contents")}</h3><div class="tut-nav"><button data-ch="-1" class="${chIdx < 0 ? "on" : ""}"><i>◉</i><span>${t("tut.hub")}</span></button>${nav}</div></aside><section class="tut-main"><div class="tut-top"><div class="brand" style="letter-spacing:.14em"><span class="brand-mark"></span><b>${t("tut.title")}</b></div><div style="display:flex;gap:8px"><button class="chip-btn" data-tutact="lang">${T.lang() === "fa" ? "English" : "فارسی"}</button><button class="chip-btn" data-tutact="close">${t("tut.close")}</button></div></div><div class="tut-body">${main}</div>${foot}</section>`;
}
function renderOverlay() { const r = $("#tutorialRoot"); const keep = r.querySelector(".tut-body"), st = keep ? keep.scrollTop : 0; r.innerHTML = `<div class="tut">${guideHTML()}</div>`; const nb = r.querySelector(".tut-nav .on"); if (nb) nb.scrollIntoView({ block: "nearest" }); }
$("#tutorialRoot").addEventListener("click", e => {
  const c = e.target.closest("[data-ch]"), a = e.target.closest("[data-tutact]");
  if (c && !c.disabled) { chIdx = +c.dataset.ch; A.play("click"); renderOverlay(); const b = $("#tutorialRoot .tut-body"); if (b) b.scrollTop = 0; }
  if (a) { A.play("click"); const k = a.dataset.tutact; if (k === "close") WOE_TUT.close(); else if (k === "lang") UI.setLang(T.lang() === "fa" ? "en" : "fa"); else if (k === "practice") WOE_TUT.startPractice(); }
});
window.WOE_TUT = {
  open(fg) { open = true; fromGame = !!fg; chIdx = -1; A.play("open"); renderOverlay(); },
  close() { open = false; $("#tutorialRoot").innerHTML = ""; A.play("close"); },
  isOpen: () => open, refresh() { if (open) renderOverlay(); if (coach.i >= 0) renderCoach(); }, stopCoach,
  async startPractice() {
    this.close(); UI.stop(); if (UI.w && !UI.tutorial) await UI.saveSilently();
    const w = E.newWorld({ worldName: t("tut.sandbox"), countryId: "CUS", nationName: t("tut.nation"), scenarioId: "modern", difficulty: "easy", mods: [] });
    UI.tutorial = true; await UI.openWorld(w); setTimeout(startCoach, 900);
  }
};
})();
